function EXTRA(R,ICON){
 /* hook: two cups of chai, and the jug they go into */
 const cup=(x,y,col)=>`<path d="M${x} ${y} h90 l-10 80 h-70 z" fill="#FFFFFF" stroke="${col}" stroke-width="4"/><rect x="${x+6}" y="${y+8}" width="78" height="18" fill="#C68B59" opacity=".8"/><path d="M${x+90} ${y+18} q26 6 0 40" fill="none" stroke="${col}" stroke-width="4"/>`+
  `<path d="M${x+30} ${y-10} q-8 -14 0 -28 M${x+55} ${y-10} q-8 -14 0 -28" fill="none" stroke="#ADB5BD" stroke-width="3"/>`;
 ICON.thCups=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${TH_box(0,0,380,170,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}${cup(40,46,ORG)}${cup(210,46,ORG)}${TH_T(85,156,'70 °C',{fs:24,fw:800,a:'middle',fill:ORG})}${TH_T(255,156,'70 °C',{fs:24,fw:800,a:'middle',fill:ORG})}${TH_T(180,100,'+',{fs:34,fw:800,a:'middle'})}</g>`;
 ICON.thJug=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${TH_box(0,0,380,170,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}<path d="M40 30 h110 l-8 120 h-94 z" fill="#FFFFFF" stroke="${BLU}" stroke-width="4"/><rect x="45" y="60" width="100" height="84" fill="#C68B59" opacity=".8"/><path d="M150 50 q36 10 0 70" fill="none" stroke="${BLU}" stroke-width="4"/>${TH_T(200,72,'2 × volume',{fs:26,fw:800,fill:BLU})}${TH_T(200,122,'140 °C ?',{fs:30,fw:800,fill:RED})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.thBoundary=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${TH_dash(20,20,160,150,BLU)}<rect x="50" y="56" width="100" height="90" rx="10" fill="#DBE4FF" stroke="${BLU}" stroke-width="4"/>${TH_dots(54,60,92,82,BLU,7)}${TH_T(100,206,'closed',{fs:26,fw:800,a:'middle',fill:BLU})}
  <rect x="220" y="70" width="190" height="50" fill="#D3F9D8" stroke="${GRN}" stroke-width="4"/>${TH_dash(270,50,90,90,GRN)}${TH_arrow(222,95,268,95,GRN,4)}${TH_arrow(362,95,408,95,GRN,4)}${TH_T(315,206,'open',{fs:26,fw:800,a:'middle',fill:GRN})}
  <rect x="140" y="232" width="140" height="80" rx="14" fill="#E9ECEF" stroke="#868E96" stroke-width="10"/>${TH_T(210,280,'isolated',{fs:24,fw:800,a:'middle',fill:'#495057'})}</g>`;
 ICON.thHalve=(x,y)=>`<g transform="translate(${x-210} ${y-165})"><rect x="10" y="40" width="400" height="190" rx="14" fill="#FFF4E6" stroke="${ORG}" stroke-width="4"/>${TH_L(210,30,210,240,'#18213A',6)}
  ${TH_T(110,110,'m = 1 kg',{fs:28,fw:800,a:'middle',fill:BLU})}${TH_T(310,110,'m = 1 kg',{fs:28,fw:800,a:'middle',fill:BLU})}${TH_T(110,170,'T = 300 K',{fs:28,fw:800,a:'middle',fill:ORG})}${TH_T(310,170,'T = 300 K',{fs:28,fw:800,a:'middle',fill:ORG})}
  ${TH_T(210,290,'m halves · T stays',{fs:28,fw:800,a:'middle'})}</g>`;
 /* the worked example's two paths, drawn from the computed states: x = 60 + 140(V − 1), y = 260 − 70(P − 0.5) */
 ICON.thPaths=(x,y)=>{const X=V=>60+140*(V-1),Y=P=>260-70*(P-.5);
  return `<g transform="translate(${x-210} ${y-165})">${TH_axes(30,295,380,280,'V (L)','P')}
  <polygon points="${X(1)},${Y(3)} ${X(2)},${Y(2)} ${X(3)},${Y(1)} ${X(2)},${Y(1.5)}" fill="${GRN}" fill-opacity=".25"/>
  <polyline points="${X(1)},${Y(3)} ${X(2)},${Y(1.5)} ${X(3)},${Y(1)}" fill="none" stroke="${BLU}" stroke-width="5"/>
  <polyline points="${X(1)},${Y(3)} ${X(2)},${Y(2)} ${X(3)},${Y(1)}" fill="none" stroke="${GRN}" stroke-width="5" stroke-dasharray="10 6"/>
  <circle cx="${X(1)}" cy="${Y(3)}" r="9" fill="#18213A"/><circle cx="${X(3)}" cy="${Y(1)}" r="9" fill="#18213A"/>
  ${TH_T(X(1)+4,Y(3)-16,'A',{fs:26,fw:800})}${TH_T(X(3)+12,Y(1)-14,'B',{fs:26,fw:800})}
  ${TH_T(X(2)+24,Y(2)-30,'4.00 J',{fs:26,fw:800,fill:GRN})}${TH_T(X(2)-30,Y(1.5)+44,'3.50 J',{fs:26,fw:800,fill:BLU})}</g>`};
}
